const ROOT_RECORD_BYTES: u64 = 333;:
}
pool.operations.pop();

// 第三段：根槽 FUA，区域 3 mod 3 = 0 的槽 1（暖机之后第一个事务是 txg 3）。

const ROOT_RECORD_BYTES: u64 = 371;:
    let digest = wide_checksum_with_field_zeroed(&bytes, SYSTEM_CONFIGURATION_SLOT_BYTES as usize, SYSTEM_CONFIGURATION_CHECKSUM_OFFSET);
    bytes[SYSTEM_CONFIGURATION_CHECKSUM_OFFSET..SYSTEM_CONFIGURATION_CHECKSUM_OFFSET + 32].copy_from_slice(&digest);
    bytes
}

const ROOT_RECORD_BYTES: u64 = 333;:
    let digest = wide_checksum_with_field_zeroed(&bytes, PHYSICAL_BLOCK_BYTES as usize, SYSTEM_CONFIGURATION_CHECKSUM_OFFSET);
    bytes[SYSTEM_CONFIGURATION_CHECKSUM_OFFSET..SYSTEM_CONFIGURATION_CHECKSUM_OFFSET + 32].copy_from_slice(&digest);
    bytes
}

let leaf_first_sector = SlotNumber(SLOT_INODE_LEAF).device_offset().0 / PHYSICAL_BLOCK_BYTES;
let leaf_sector_count = DATA_UNIT_BYTES / PHYSICAL_BLOCK_BYTES;
let mut sectors: std::collections::BTreeSet<u64> = old.devices[device_index].sectors.keys().copied().filter(|sector| *sector >= leaf_first_sector && *sector < leaf_first_sector + leaf_sector_count).collect();
sectors.extend(new.devices[device_index].sectors.keys().copied().filter(|sector| *sector >= leaf_first_sector && *sector < leaf_first_sector + leaf_sector_count));

for _location in &self.locations {
    LocationEntry { device: DeviceIdentity(0), slot: SlotNumber(0), unit_checksum: 0 }.write_to(writer);
}
writer.put_u8(self.unit_class);
